using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // HasIndex removed: Cosmos DB indexing is managed via the container's
        // indexing policy (Azure Portal / Bicep / Terraform), not EF Core.
        // In EF Core 9 HasIndex throws InvalidOperationException for Cosmos entities.

        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // Preserve EF Core 8 discriminator property name so existing 500K documents
            // (which store "Discriminator": "Product") remain readable by both EF Core
            // and direct Cosmos SQL queries that reference c.Discriminator.
            entity.HasDiscriminator<string>("Discriminator");

            // Preserve EF Core 8 compound id format ("Product|123") so FindAsync and
            // point-reads continue to resolve existing documents.
            entity.HasRootDiscriminatorInJsonId(true);
        });
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

